function Lines({ items }: { items: { title: string; extra: string[] }[] }) {
  return (
    <Stack gap={10}>
      {items.map((item) => (
        <Stack key={item.title} gap={2}>
          <Text size="small" weight="semibold">
            {item.title}
          </Text>
          {item.extra.filter(Boolean).map((line) => (
            <Text key={line} size="small" tone="secondary">
              {line}
            </Text>
          ))}
        </Stack>
      ))}
    </Stack>
  );
}

export default function TkachShotsReport() {
  return (
    <Stack gap={16}>
      <H1>Отчёт группы нод · Ткач</H1>
      <Text tone="secondary">
        Проект #29 · живая БД · ячеек 115 · бит 145 · сцен 146 · кадров 145
      </Text>
      <Callout tone="info" title="Цепь">
        Закадр → биты → главное действие (сцены) → кадры. Самостоятельный = новый
        сетап. Родитель = то же место.
      </Callout>
      <Table
        stickyHeader
        striped
        headers={["id", "Закадр ячейки", "Биты", "Главное действие (сцены)", "Кадры"]}
        columnAlign={["center", "left", "left", "left", "left"]}
        rows={CELLS.map((c) => [
          <Text key={c.id} weight="semibold">
            {c.id}
          </Text>,
          <Text key={c.id + "-vo"} size="small">
            {c.vo}
          </Text>,
          <Lines
            key={c.id + "-bits"}
            items={c.bits.map((b) => ({ title: b.t, extra: [b.a] }))}
          />,
          <Lines
            key={c.id + "-scenes"}
            items={c.scenes.map((s) => ({ title: s.t, extra: [s.v] }))}
          />,
          <Lines
            key={c.id + "-shots"}
            items={c.shots.map((s) => ({ title: s.t, extra: [s.v, s.r] }))}
          />,
        ])}
      />
    </Stack>
  );
}
